content:
{
  "criteria": [
    {
      "kind": "inclusion",
      "text": "Histopathologically-confirmed diagnosis of malignant melanoma that is metastatic or unresectable at Screening.",
      "quote": "Histopathologically-confirmed diagnosis of malignant melanoma that is metastatic or unresectable at Screening."
    },
    {
      "kind": "inclusion",
      "text": "Known BRAF mutation status; if BRAF V600 mutation positive, must have had prior treatment with a local Health Authority approved BRAF inhibitor, with or without MEK inhibitor. Patients with BRAF V600 mutations who refuse a BRAF inhibitor will not be eligible.",
      "quote": "Known BRAF mutation status; if BRAF V600 mutation positive, must have had prior treatment with a local Health Authority approved BRAF inhibitor, with or without MEK inhibitor. Patients with BRAF V600 mutations who refuse a BRAF inhibitor will not be eligible."
    },
    {
      "kind": "inclusion",
      "text": "Refractory to PD-1 blockade either as monotherapy or in combination with other therapies, as defined by the following criteria: a. Received treatment with a Food and Drug Administration approved PD-1 blocking antibody for 12 weeks or longer. b. Have PD (according to RECIST v1.1) within 12 weeks of the last dose of a PD-1 blocking antibody, either as monotherapy or in combination with other agents. Evidence of confirmed PD must be established by Investigator assessment at least 4 weeks after the initial date of PD. The confirmatory assessment may serve as the Baseline for this study if completed within 30 days before the start of study treatment. NOTE: in subjects with histologically confirmed recurrence on or after adjuvant PD-1 blocking antibody, confirmatory imaging is not required.",
      "quote": "Refractory to PD-1 blockade either as monotherapy or in combination with other therapies, as defined by the following criteria: a. Received treatment with a Food and Drug Administration approved PD-1 blocking antibody for 12 weeks or longer. b. Have PD (according to RECIST v1.1) within 12 weeks of the last dose of a PD-1 blocking antibody, either as monotherapy or in combination with other agents. Evidence of confirmed PD must be established by Investigator assessment at least 4 weeks after the initial date of PD. The confirmatory assessment may serve as the Baseline for this study if completed within 30 days before the start of study treatment. NOTE: in subjects with histologically confirmed recurrence on or after adjuvant PD-1 blocking antibody, confirmatory imaging is not required."
    },
    {
      "kind": "inclusion",
      "text": "Measurable disease, as defined by RECIST v1.1 and all of the following: a. At least 1 accessible lesion amenable to repeated IT injection. b. One or more measurable lesions at least 1 cm in diameter that are not intended for CMP-001 injection and can be followed as target lesions per RECIST v1.1. c. Documented disease progression in any lesion that was previously radiated in order to serve as a target lesion.",
      "quote": "Measurable disease, as defined by RECIST v1.1 and all of the following: a. At least 1 accessible lesion amenable to repeated IT injection. b. One or more measurable lesions at least 1 cm in diameter that are not intended for CMP-001 injection and can be followed as target lesions per RECIST v1.1. c. Documented disease progression in any lesion that was previously radiated in order to serve as a target lesion."
    },
    {
      "kind": "inclusion",
      "text": "Able to provide tissue from a core or excisional/incisional biopsy (fine needle aspirate is not sufficient). A fresh tissue biopsy (within 90 days before the start of study treatment) is preferred but an archival sample is acceptable (as a substitute) if no intervening therapy was received. If the Investigator believes it is unsafe to perform a biopsy, the subject may be considered eligible after discussion with the Medical Monitor if tissue and/or prior assessments are available to determine programmed death-ligand 1 expression.",
      "quote": "Able to provide tissue from a core or excisional/incisional biopsy (fine needle aspirate is not sufficient). A fresh tissue biopsy (within 90 days before the start of study treatment) is preferred but an archival sample is acceptable (as a substitute) if no intervening therapy was received. If the Investigator believes it is unsafe to perform a biopsy, the subject may be considered eligible after discussion with the Medical Monitor if tissue and/or prior assessments are available to determine programmed death-ligand 1 expression."
    },
    {
      "kind": "inclusion",
      "text": "Adequate organ function based on most recent laboratory values within 3 weeks before first dose of study treatment on Week 1 Day 1 (W1D1): a. Bone marrow function: neutrophil count ≥ 1500/mm3, platelet count ≥ 100,000/mm3, hemoglobin concentration ≥ 9 g/dL, white blood cells ≥ 2000/mm3. b. Liver function: total bilirubin ≤ 1.5 times the upper limit of normal (ULN) with the following exception: subjects with Gilbert Disease total serum bilirubin ≤ 3 times ULN; aspartate aminotransferase and alanine aminotransferase ≤ 3 times the ULN. c. Lactate dehydrogenase ≤ 2 times the ULN. d. Renal function: estimated (Cockcroft-Gault) or measured creatinine clearance ≥ 30 mL/min. e. Coagulation: International normalized ratio or prothrombin time (PT) ≤ 1.5 times ULN, unless subject is receiving anticoagulant therapy, as long as PT or partial thromboplastin time (PTT) is within therapeutic range of intended use of anticoagulants; Activated partial thromboplastin time or PTT ≤ 1.5 times ULN, unless subject is receiving anticoagulant therapy, as long as PT or PTT is within therapeutic range of intended use of anticoagulants.",
      "quote": "Adequate organ function based on most recent laboratory values within 3 weeks before first dose of study treatment on Week 1 Day 1 (W1D1): a. Bone marrow function: neutrophil count ≥ 1500/mm3, platelet count ≥ 100,000/mm3, hemoglobin concentration ≥ 9 g/dL, white blood cells ≥ 2000/mm3. b. Liver function: total bilirubin ≤ 1.5 times the upper limit of normal (ULN) with the following exception: subjects with Gilbert Disease total serum bilirubin ≤ 3 times ULN; aspartate aminotransferase and alanine aminotransferase ≤ 3 times the ULN. c. Lactate dehydrogenase ≤ 2 times the ULN. d. Renal function: estimated (Cockcroft-Gault) or measured creatinine clearance ≥ 30 mL/min. e. Coagulation: International normalized ratio or prothrombin time (PT) ≤ 1.5 times ULN, unless subject is receiving anticoagulant therapy, as long as PT or partial thromboplastin time (PTT) is within therapeutic range of intended use of anticoagulants; Activated partial thromboplastin time or PTT ≤ 1.5 times ULN, unless subject is receiving anticoagulant therapy, as long as PT or PTT is within therapeutic range of intended use of anticoagulants.",
      "thresholds": [
        {"test": "neutrophil count", "op": ">=", "value": 1500, "unit": "/mm3"},
        {"test": "platelet count", "op": ">=", "value": 100000, "unit": "/mm3"},
        {"test": "hemoglobin", "op": ">=", "value": 9, "unit": "g/dL"},
        {"test": "white blood cells", "op": ">=", "value": 2000, "unit": "/mm3"},
        {"test": "total bilirubin", "op": "<=", "value": 1.5, "unit": "x ULN"},
        {"test": "total serum bilirubin (Gilbert Disease)", "op": "<=", "value": 3, "unit": "x ULN"},
        {"test": "aspartate aminotransferase", "op": "<=", "value": 3, "unit": "x ULN"},
        {"test": "alanine aminotransferase", "op": "<=", "value": 3, "unit": "x ULN"},
        {"test": "lactate dehydrogenase", "op": "<=", "value": 2, "unit": "x ULN"},
        {"test": "creatinine clearance", "op": ">=", "value": 30, "unit": "mL/min"},
        {"test": "INR or PT", "op": "<=", "value": 1.5, "unit": "x ULN"},
        {"test": "aPTT or PTT", "op": "<=", "value": 1.5, "unit": "x ULN"}
      ]
    },
    {
      "kind": "inclusion",
      "text": "Age ≥ 18 years at time of consent.",
      "quote": "Age ≥ 18 years at time of consent."
    },
    {
      "kind": "inclusion",
      "text": "Eastern Cooperative Oncology Group Performance Status of 0 to 1 at Screening.",
      "quote": "Eastern Cooperative Oncology Group Performance Status of 0 to 1 at Screening."
    },
    {
      "kind": "inclusion",
      "text": "Capable of understanding and complying with protocol requirements.",
      "quote": "Capable of understanding and complying with protocol requirements."
    },
    {
      "kind": "inclusion",
      "text": "Women of childbearing potential must have negative serum pregnancy test before dosing at W1D1 and be willing to use an adequate method of contraception (Section 4.3.2.) from the time of consent until at least 150 days after last dose of study treatment.",
      "quote": "Women of childbearing potential must have negative serum pregnancy test before dosing at W1D1 and be willing to use an adequate method of contraception (Section 4.3.2.) from the time of consent until at least 150 days after last dose of study treatment."
    },
    {
      "kind": "inclusion",
      "text": "Able and willing to provide written informed consent and to follow study instructions. Subjects unable to provide written informed consent on their own behalf will not be eligible for the study.",
      "quote": "Able and willing to provide written informed consent and to follow study instructions. Subjects unable to provide written informed consent on their own behalf will not be eligible for the study."
    },
    {
      "kind": "exclusion",
      "text": "Uveal, acral, or mucosal melanoma.",
      "quote": "Uveal, acral, or mucosal melanoma."
    },
    {
      "kind": "exclusion",
      "text": "Received radiation therapy (or other nonsystemic therapy) within 2 weeks before first dose of study treatment on W1D1. Subjects should have recovered (ie, Grade ≤1 or at Baseline) from radiation-related toxicities.",
      "quote": "Received radiation therapy (or other nonsystemic therapy) within 2 weeks before first dose of study treatment on W1D1. Subjects should have recovered (ie, Grade ≤1 or at Baseline) from radiation-related toxicities."
    },
    {
      "kind": "exclusion",
      "text": "Treatment with complementary medications (eg, herbal supplements or traditional Chinese medicines) to treat the disease under study within 2 weeks before start of study treatment. Refer to Section 4.4. for prohibited therapies.",
      "quote": "Treatment with complementary medications (eg, herbal supplements or traditional Chinese medicines) to treat the disease under study within 2 weeks before start of study treatment. Refer to Section 4.4. for prohibited therapies."
    },
    {
      "kind": "exclusion",
      "text": "Received systemic pharmacologic doses of corticosteroids > 10 mg/day prednisone within 30 days before first dose of study treatment on W1D1. a. Subjects who are currently receiving steroids at a prednisone-equivalent dose of ≤ 10 mg/day do not need to discontinue steroids before enrollment. b. Replacement doses, topical, ophthalmologic, and inhalational steroids are permitted. c. Stress-dose corticosteroids will be required in subjects with adrenal insufficiency (see Section 5.1.2.1.1.).",
      "quote": "Received systemic pharmacologic doses of corticosteroids > 10 mg/day prednisone within 30 days before first dose of study treatment on W1D1. a. Subjects who are currently receiving steroids at a prednisone-equivalent dose of ≤ 10 mg/day do not need to discontinue steroids before enrollment. b. Replacement doses, topical, ophthalmologic, and inhalational steroids are permitted. c. Stress-dose corticosteroids will be required in subjects with adrenal insufficiency (see Section 5.1.2.1.1.)."
    },
    {
      "kind": "exclusion",
      "text": "History of immune-related AE that required permanent discontinuation of PD-1 blocking antibody.",
      "quote": "History of immune-related AE that required permanent discontinuation of PD-1 blocking antibody."
    },
    {
      "kind": "exclusion",
      "text": "Not fully recovered from AEs (to Grade 1 or less [per CTCAE v5.0], with the exception of persistent adverse events or sequelae, eg, vitiligo, alopecia, hypothyroidism, diabetes mellitus, and adrenal and/or pituitary insufficiency) due to prior treatment. NOTE: Subjects previously treated with a CTLA-4–blocking antibody, subjects receiving corticosteroids with daily doses > 5 mg and ≤ 10 mg of prednisone equivalent for > 2 weeks, and subjects with clinical symptoms and/or laboratory findings suggesting risk for adrenal insufficiency should undergo diagnostic tests for adrenal insufficiency via local laboratory.",
      "quote": "Not fully recovered from AEs (to Grade 1 or less [per CTCAE v5.0], with the exception of persistent adverse events or sequelae, eg, vitiligo, alopecia, hypothyroidism, diabetes mellitus, and adrenal and/or pituitary insufficiency) due to prior treatment. NOTE: Subjects previously treated with a CTLA-4–blocking antibody, subjects receiving corticosteroids with daily doses > 5 mg and ≤ 10 mg of prednisone equivalent for > 2 weeks, and subjects with clinical symptoms and/or laboratory findings suggesting risk for adrenal insufficiency should undergo diagnostic tests for adrenal insufficiency via local laboratory."
    },
    {
      "kind": "exclusion",
      "text": "Active pneumonitis or history of noninfectious pneumonitis that required steroids.",
      "quote": "Active pneumonitis or history of noninfectious pneumonitis that required steroids."
    },
    {
      "kind": "exclusion",
      "text": "Severe uncontrolled cardiac disease within 6 months of Screening, including but not limited to poorly controlled hypertension, unstable angina, myocardial infarction, congestive heart failure (New York Heart Association Class II or greater), pericarditis within the previous 6 months, cerebrovascular accident, or implanted or continuous use of a pacemaker or defibrillator.",
      "quote": "Severe uncontrolled cardiac disease within 6 months of Screening, including but not limited to poorly controlled hypertension, unstable angina, myocardial infarction, congestive heart failure (New York Heart Association Class II or greater), pericarditis within the previous 6 months, cerebrovascular accident, or implanted or continuous use of a pacemaker or defibrillator."
    },
    {
      "kind": "exclusion",
      "text": "Known history of immunodeficiency.",
      "quote": "Known history of immunodeficiency."
    },
    {
      "kind": "exclusion",
      "text": "Known additional malignancy that is progressing or required active treatment within the past 3 years. Exceptions include cancers that have undergone potentially curative therapy, eg, basal cell carcinoma of the skin, squamous cell carcinoma of the skin, localized prostate cancer with prostate-specific antigen level below 4.0 ng/mL, in situ cervical cancer on biopsy or a squamous intraepithelial lesion on Papanicolaou smear, and thyroid cancer (except anaplastic), in situ breast cancer, and adjuvant hormonal therapy for breast cancer > 3 years from curative-intent surgical resection.",
      "quote": "Known additional malignancy that is progressing or required active treatment within the past 3 years. Exceptions include cancers that have undergone potentially curative therapy, eg, basal cell carcinoma of the skin, squamous cell carcinoma of the skin, localized prostate cancer with prostate-specific antigen level below 4.0 ng/mL, in situ cervical cancer on biopsy or a squamous intraepithelial lesion on Papanicolaou smear, and thyroid cancer (except anaplastic), in situ breast cancer, and adjuvant hormonal therapy for breast cancer > 3 years from curative-intent surgical resection."
    },
    {
      "kind": "exclusion",
      "text": "Active autoimmune disease that has required systemic treatment in past 2 years; replacement therapy is not considered a form of systemic treatment.",
      "quote": "Active autoimmune disease that has required systemic treatment in past 2 years; replacement therapy is not considered a form of systemic treatment."
    },
    {
      "kind": "exclusion",
      "text": "Untreated, symptomatic, or enlarging central nervous system metastases or carcinomatous meningitis (including leptomeningeal metastases from solid tumors).",
      "quote": "Untreated, symptomatic, or enlarging central nervous system metastases or carcinomatous meningitis (including leptomeningeal metastases from solid tumors)."
    },
    {
      "kind": "exclusion",
      "text": "Prior allogenic tissue/solid organ transplant.",
      "quote": "Prior allogenic tissue/solid organ transplant."
    },
    {
      "kind": "exclusion",
      "text": "Active infection requiring systemic therapy.",
      "quote": "Active infection requiring systemic therapy."
    },
    {
      "kind": "exclusion",
      "text": "Known or suspected active infection with severe acute respiratory syndrome coronavirus 2 virus.",
      "quote": "Known or suspected active infection with severe acute respiratory syndrome coronavirus 2 virus."
    },
    {
      "kind": "exclusion",
      "text": "Known or suspected active infection with human immunodeficiency virus, hepatitis B virus, or hepatitis C virus (testing is not required unless suspected).",
      "quote": "Known or suspected active infection with human immunodeficiency virus, hepatitis B virus, or hepatitis C virus (testing is not required unless suspected)."
    },
    {
      "kind": "exclusion",
      "text": "Received a live virus/attenuated vaccination within 30 days before first dose of study treatment on W1D1.",
      "quote": "Received a live virus/attenuated vaccination within 30 days before first dose of study treatment on W1D1."
    },
    {
      "kind": "exclusion",
      "text": "Received blood products (including platelets or red blood cells) or colony stimulating factors (including granulocyte colony stimulating factor, granulocyte/macrophage colony stimulating factor, or recombinant erythropoietin) within 30 days before the start of Screening.",
      "quote": "Received blood products (including platelets or red blood cells) or colony stimulating factors (including granulocyte colony stimulating factor, granulocyte/macrophage colony stimulating factor, or recombinant erythropoietin) within 30 days before the start of Screening."
    },
    {
      "kind": "exclusion",
      "text": "History of permanent discontinuation of nivolumab due to infusion reactions.",
      "quote": "History of permanent discontinuation of nivolumab due to infusion reactions."
    },
    {
      "kind": "exclusion",
      "text": "Any concurrent uncontrolled illness, including mental illness or substance abuse, which in the opinion of the Investigator would make the subject unable to cooperate or participate in the study.",
      "quote": "Any concurrent uncontrolled illness, including mental illness or substance abuse, which in the opinion of the Investigator would make the subject unable to cooperate or participate in the study."
    },
    {
      "kind": "exclusion",
      "text": "Participation in another clinical study of an investigational anticancer therapy or device within 30 days before first dose of study treatment on W1D1. NOTE: Participation in the follow-up phase (receiving no study treatment) of a prior study is allowed.",
      "quote": "Participation in another clinical study of an investigational anticancer therapy or device within 30 days before first dose of study treatment on W1D1. NOTE: Participation in the follow-up phase (receiving no study treatment) of a prior study is allowed."
    },
    {
      "kind": "exclusion",
      "text": "Requires prohibited treatment (ie, non-protocol specified anticancer pharmacotherapy, surgery, or radiotherapy) for treatment of malignant tumor.",
      "quote": "Requires prohibited treatment (ie, non-protocol specified anticancer pharmacotherapy, surgery, or radiotherapy) for treatment of malignant tumor."
    },
    {
      "kind": "exclusion",
      "text": "Has a life expectancy of less than 3 months and/or has rapidly progressing disease (eg, tumor bleeding, uncontrolled tumor pain) in the opinion of the treating Investigator.",
      "quote": "Has a life expectancy of less than 3 months and/or has rapidly progressing disease (eg, tumor bleeding, uncontrolled tumor pain) in the opinion of the treating Investigator."
    },
    {
      "kind": "exclusion",
      "text": "Received previous CMP-001 treatment.",
      "quote": "Received previous CMP-001 treatment."
    },
    {
      "kind": "exclusion",
      "text": "Pregnant or breastfeeding or expecting to conceive or donate eggs within the projected duration of the study, from the time of consent until at least 150 days after last dose of study treatment for women.",
      "quote": "Pregnant or breastfeeding or expecting to conceive or donate eggs within the projected duration of the study, from the time of consent until at least 150 days after last dose of study treatment for women."
    }
  ]
}
